import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, copyFileSync, mkdirSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';
const root='F:/VisibleMedicine/staging/20261022-viewer-assurance-candidate';
const website=root+'/website', step=root+'/delivery-admission';
const sha=b=>createHash('sha256').update(b).digest('hex'),read=p=>readFileSync(website+'/'+p),json=p=>JSON.parse(read(p));
assert(!existsSync(step),'Create-only admission');
const built=JSON.parse(readFileSync(root+'/viewer-build/VERIFIED.json'));
assert.equal(built.review,'4db82d92f6de502a342396d290380253aff46ef754b23e6161672d40c9abce99');
const currentPath='tests/fixtures/current-atlas-delivery.json';
const beforeBytes=read(currentPath),before=JSON.parse(beforeBytes);
assert.equal(sha(beforeBytes),'3e69cdcae68524ad65a6b542fa7c7d51180c676a3f43b187dcb39d55de95ddeb');
const changed=['atlas-review/integration-inputs.json','atlas-review/manifest.json','public/atlas-review-viewer/manifest.json'];
const next=structuredClone(before);next.reviewIntegration=built.review;
for(const path of changed)next.documents[path]=sha(read(path));
assert.deepEqual(Object.keys(before.documents).filter(path=>before.documents[path]!==next.documents[path]).sort(),changed);
const inverse=structuredClone(next);inverse.reviewIntegration=before.reviewIntegration;
for(const path of changed)inverse.documents[path]=before.documents[path];
assert.deepEqual(inverse,before,'No source/tree/model/runtime/count or clearance change');
const binding=json('atlas-review/integration-inputs.json');assert.equal(binding.inputs.length,1723);
const oldBinding=JSON.parse(readFileSync('F:/VisibleMedicine/website/atlas-review/integration-inputs.json'));
assert.equal(oldBinding.sha256,before.reviewIntegration);
const oldRows=new Map(oldBinding.inputs.map(row=>[row.path,row]));
assert.deepEqual(binding.inputs.filter(row=>!oldRows.has(row.path)).map(row=>row.path).sort(),['components/atlas-runtime-expansion.ts','components/atlas-runtime-frame.css']);
assert.deepEqual(binding.inputs.filter(row=>oldRows.has(row.path)&&oldRows.get(row.path).sha256!==row.sha256).map(row=>row.path).sort(),['components/AtlasRuntimeFrame.tsx','scripts/bind-clinical-review.mjs']);
for(const row of binding.inputs)assert.equal(sha(read(row.path)),row.sha256,row.path);
mkdirSync(step);const fixture=website+'/tests/fixtures/expanded-review-admission';mkdirSync(fixture);
copyFileSync(website+'/'+currentPath,fixture+'/current-atlas-delivery.json.raw');
copyFileSync(website+'/tests/current-atlas-delivery.test.mjs',fixture+'/current-atlas-delivery.test.mjs.raw');
const originalTestSha=sha(read('tests/current-atlas-delivery.test.mjs'));
writeFileSync(website+'/'+currentPath,JSON.stringify(next,null,2)+'\n');
const {validateCurrentAtlasDelivery}=await import(pathToFileURL(website+'/tests/current-atlas-delivery.mjs').href);
assert.deepEqual(validateCurrentAtlasDelivery({pin:next,root:website}),next);
assert.throws(()=>validateCurrentAtlasDelivery({pin:before,root:website}));
const validation=spawnSync(process.execPath,['scripts/verify-clinical-review.mjs'],{cwd:website,windowsHide:true,encoding:'utf8',env:{...process.env,GOMAXPROCS:'2',RAYON_NUM_THREADS:'1'},maxBuffer:8*1024*1024});
writeFileSync(step+'/stock-review.log',(validation.stdout??'')+(validation.stderr??''),{flag:'wx'});
const receipt={at:new Date().toISOString(),website,source:next.source,sourceTree:next.sourceTree,oldReview:before.reviewIntegration,review:next.reviewIntegration,pinSha256:sha(read(currentPath)),originalPinSha256:sha(beforeBytes),originalTestSha256:originalTestSha,changedDocuments:changed,bindings:binding.inputs.length,imports:next.reviewSourceFiles,viewerFiles:next.viewerFiles,packages:next.viewerPackages,stockReviewExit:validation.status,stockReviewLogSha256:sha(readFileSync(step+'/stock-review.log')),ownerPreviewChanged:false,clinicalApproval:false};
writeFileSync(step+'/ADMITTED.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});
assert.equal(validation.status,0,'Stock Review verification failed; retain admission receipt/log');
console.log(JSON.stringify(receipt));
